import (
	"sync"
	"testing"
)

func ConcurrentSquares(nums []int) []int {
	var results []int
	var mu sync.Mutex
	var wg sync.WaitGroup

	for _, n := range nums {
		wg.Add(1)
		go func(val int) {
			defer wg.Done()
			sq := val * val
			mu.Lock()
			results = append(results, sq)
			mu.Unlock()
		}(n)
	}

	wg.Wait()
	return results
}

func TestConcurrentSquares(t *testing.T) {
	nums := []int{1, 2, 3, 4, 5}
	res := ConcurrentSquares(nums)
	if len(res) != 5 {
		t.Errorf("expected 5 results, got %d", len(res))
	}
}

